package main

import (
	"encoding/json"
	"fmt"
	"os"
	"os/exec"

	"github.com/gofiber/fiber/v2"
)

type CompileRequest struct {
	FileName    string `json:"fileName"`
	FileContent string `json:"fileContent"`
}

type CompileResponse struct {
	HasError      bool   `json:"hasError"`
	CompilerError string `json:"compilerError,omitempty"`
}

func compileCode(fileName, fileContent string) (bool, string) {
	// Create a temporary file for the code
	tmpFile, err := os.CreateTemp("", fileName)
	if err != nil {
		return true, fmt.Sprintf("Error creating temp file: %v", err)
	}
	defer os.Remove(tmpFile.Name()) // Clean up the temp file

	// Write the file content to the temporary file
	if _, err := tmpFile.WriteString(fileContent); err != nil {
		return true, fmt.Sprintf("Error writing to temp file: %v", err)
	}
	tmpFile.Close()

	// Determine the file extension to choose the compiler
	var cmd *exec.Cmd
	if len(fileName) > 3 && fileName[len(fileName)-3:] == ".ts" {
		cmd = exec.Command("tsc", tmpFile.Name())
	} else if len(fileName) > 4 && fileName[len(fileName)-4:] == ".cpp" {
		cmd = exec.Command("g++", tmpFile.Name(), "-o", "/dev/null")
	} else {
		return true, "Unsupported file type. Only .ts and .cpp are allowed."
	}

	// Run the compiler command and capture the output
	output, err := cmd.CombinedOutput()
	if err != nil {
		return true, string(output) // Return the compiler error output
	}

	return false, "" // No error
}

func compileHandler(c *fiber.Ctx) error {
	var req CompileRequest
	if err := c.BodyParser(&req); err != nil {
		return c.Status(fiber.StatusBadRequest).JSON(CompileResponse{HasError: true, CompilerError: "Invalid request body"})
	}

	hasError, compilerError := compileCode(req.FileName, req.FileContent)
	return c.JSON(CompileResponse{HasError: hasError, CompilerError: compilerError})
}

func main() {
	app := fiber.New()

	app.Post("/compile", compileHandler)

	if err := app.Listen(":5000"); err != nil {
		fmt.Printf("Error starting server: %v\n", err)
	}
}

package main

import (
    "database/sql"
    "fmt"
    "log"
    "net/http"
    "os"
    "time"

    "github.com/gofiber/fiber/v2"
    _ "github.com/mattn/go-sqlite3"
    "github.com/google/uuid"
)

var db *sql.DB

func init() {
    var err error
    db, err = sql.Open("sqlite3", "db.sqlite3")
    if err != nil {
        log.Fatal(err)
    }

    // Create the clicks table if it doesn't exist
    createTableSQL := `CREATE TABLE IF NOT EXISTS clicks (
        id TEXT PRIMARY KEY,
        timestamp DATETIME
    );`
    if _, err := db.Exec(createTableSQL); err != nil {
        log.Fatal(err)
    }
}

func registerClick(c *fiber.Ctx) error {
    clickID := uuid.New().String()
    timestamp := time.Now()

    _, err := db.Exec("INSERT INTO clicks (id, timestamp) VALUES (?, ?)", clickID, timestamp)
    if err != nil {
        return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request"})
    }

    return c.Status(http.StatusCreated).JSON(fiber.Map{"id": clickID, "timestamp": timestamp})
}

func retrieveClicks(c *fiber.Ctx) error {
    date := c.Query("date")
    direction := c.Query("direction")

    if date == "" || direction == "" {
        return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request"})
    }

    var operator string
    switch direction {
    case "<":
        operator = "<"
    case "<=":
        operator = "<="
    case ">":
        operator = ">"
    case ">=":
        operator = ">="
    default:
        return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request"})
    }

    query := fmt.Sprintf("SELECT id, timestamp FROM clicks WHERE timestamp %s ?", operator)
    rows, err := db.Query(query, date)
    if err != nil {
        return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid request"})
    }
    defer rows.Close()

    var clicks []fiber.Map
    for rows.Next() {
        var id string
        var timestamp time.Time
        if err := rows.Scan(&id, &timestamp); err != nil {
            return c.Status(http.StatusInternalServerError).JSON(fiber.Map{"error": "Internal server error"})
        }
        clicks = append(clicks, fiber.Map{"id": id, "timestamp": timestamp})
    }

    if len(clicks) == 0 {
        return c.Status(http.StatusNotFound).JSON(fiber.Map{"error": "No clicks found"})
    }

    return c.JSON(clicks)
}

func main() {
    app := fiber.New()

    app.Post("/click", registerClick)
    app.Get("/clicks", retrieveClicks)

    log.Fatal(app.Listen(":5000"))
}

package main

import (
	"encoding/json"
	"fmt"
	"io/ioutil"
	"net/http"
	"os"
	"path/filepath"
	"strings"

	"github.com/gofiber/fiber/v2"
)

const dataDir = "./data"

type SearchRequest struct {
	SearchContent  *string `json:"search_content"`
	SearchFilename *string `json:"search_filename"`
	SearchDir      *string `json:"search_dir"`
}

type SearchResponse struct {
	Files []string `json:"files"`
}

func main() {
	app := fiber.New()

	app.Post("/search", func(c *fiber.Ctx) error {
		var req SearchRequest
		if err := c.BodyParser(&req); err != nil {
			return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid input"})
		}

		searchDir := dataDir
		if req.SearchDir != nil {
			// Sanitize and validate the search directory
			if !isValidDirectory(*req.SearchDir) {
				return c.Status(http.StatusBadRequest).JSON(fiber.Map{"error": "Invalid directory"})
			}
			searchDir = filepath.Join(dataDir, *req.SearchDir)
		}

		files, err := searchFiles(searchDir, req.SearchContent, req.SearchFilename)
		if err != nil {
			return c.Status(http.StatusInternalServerError).JSON(fiber.Map{"error": "Internal server error"})
		}

		return c.JSON(SearchResponse{Files: files})
	})

	app.Listen(":5000")
}

func isValidDirectory(dir string) bool {
	// Ensure the directory is relative and does not contain any path traversal characters
	absPath, err := filepath.Abs(dir)
	if err != nil {
		return false
	}
	return strings.HasPrefix(absPath, filepath.Join(dataDir, "")) // Ensure it is within the data directory
}

func searchFiles(searchDir string, content *string, filename *string) ([]string, error) {
	var matchedFiles []string

	err := filepath.Walk(searchDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if info.IsDir() {
			return nil
		}

		if filename != nil && !strings.Contains(info.Name(), *filename) {
			return nil
		}

		if content != nil {
			fileContent, err := ioutil.ReadFile(path)
			if err != nil {
				return err
			}
			if !strings.Contains(string(fileContent), *content) {
				return nil
			}
		}

		matchedFiles = append(matchedFiles, path)
		return nil
	})

	if err != nil {
		return nil, err
	}

	return matchedFiles, nil
}

package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"regexp"
	"log"
	"os"

