      const writeStream = fs.createWriteStream(filePath);
      await new Promise((resolve, reject) => {
        data.pipe(writeStream);
        data.on('end', resolve);
        data.on('error', reject);
      });
      images.push(filePath);
      data = await request.file();
    }
