        ctx.status = 400;
        ctx.body = { error: 'Invalid input or missing files.' };
        return;
    }

    const outputFilePath = path.join('uploads', 'concatenated.pdf');
    const inputFiles = files.map(file => file.path).join(' ');

    // Use pdfunite to concatenate PDF files
