import aiohttp
from aiohttp import web
import subprocess
import re
import json

async def monitor_processes(request):
    try:
        # Parse the JSON request body
        data = await request.json()
        command_regex = data.get('command_regex')
        filter_flags = data.get('filter_flags', '')

        # Validate the command_regex input
        if not isinstance(command_regex, str) or not command_regex:
            return web.json_response({'code': 400, 'message': 'Invalid command_regex'}, status=400)

        # Construct the command securely
        command = ['ps'] + filter_flags.split() + ['-eo', 'pid,comm']

        # Execute the command
        result = subprocess.run(command, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True)
        output = result.stdout.decode()

        # Filter the output based on the command_regex
        process_list = []
        for line in output.splitlines()[1:]:  # Skip the header line
            parts = line.split(maxsplit=1)
            if len(parts) < 2:
                continue
            pid, process_string = parts
            if re.search(command_regex, process_string):
                process_list.append({'processId': int(pid), 'processString': process_string})

        return web.json_response(process_list)

    except subprocess.CalledProcessError as e:
        return web.json_response({'code': 500, 'message': 'Error executing command'}, status=500)
    except json.JSONDecodeError:
        return web.json_response({'code': 400, 'message': 'Invalid JSON'}, status=400)
    except Exception as e:
        return web.json_response({'code': 500, 'message': str(e)}, status=500)

app = web.Application()
app.router.add_post('/monitor/commands', monitor_processes)

if __name__ == '__main__':
    web.run_app(app, host='0.0.0.0', port=5000)

import os
import subprocess
from aiohttp import web
import json

async def concatenate_pdfs(request):
    # Validate and sanitize input
    data = await request.post()
    files = data.getall('files')

    if not files or not all(isinstance(file, str) for file in files):
        return web.json_response({'error': 'Invalid input or missing files.'}, status=400)

    # Create a temporary directory to store uploaded files
    temp_dir = '/tmp/pdf_concatenation'
    os.makedirs(temp_dir, exist_ok=True)

    pdf_paths = []
    try:
        for file in files:
            # Save the uploaded PDF files to the temporary directory
            file_data = await request.multipart()
            while True:
                part = await file_data.next()
                if part is None:
                    break
                if part.name == 'files':
                    filename = part.filename
                    if not filename.endswith('.pdf'):
                        return web.json_response({'error': 'Only PDF files are allowed.'}, status=400)
                    file_path = os.path.join(temp_dir, filename)
                    with open(file_path, 'wb') as f:
                        while True:
                            chunk = await part.read_chunk()  # 8192 bytes by default
                            if not chunk:
                                break
                            f.write(chunk)
                    pdf_paths.append(file_path)

        # Define the output file path
        output_pdf_path = os.path.join(temp_dir, 'concatenated.pdf')

        # Use pdfunite to concatenate the PDF files
        subprocess.run(['pdfunite'] + pdf_paths + [output_pdf_path], check=True)

        # Read the concatenated PDF file and return it in the response
        with open(output_pdf_path, 'rb') as f:
            pdf_content = f.read()

        return web.Response(body=pdf_content, content_type='application/pdf')

    except Exception as e:
        return web.json_response({'error': 'An error occurred while processing the files.'}, status=500)

    finally:
        # Clean up temporary files
        for pdf_path in pdf_paths:
            if os.path.exists(pdf_path):
                os.remove(pdf_path)
        if os.path.exists(output_pdf_path):
            os.remove(output_pdf_path)

