        Ok(Message {
            content: row.get(0)?,
            username: row.get(1)?,
        })
    }).collect();

    match messages {
        Ok(msgs) => HttpResponse::Ok().json(msgs),
        Err(_) => HttpResponse::InternalServerError().finish(),
