async fn upload_image(mut payload: Multipart) -> impl Responder {
    let mut file_path: Option<PathBuf> = None;

    while let Ok(Some(mut field)) = payload.try_next().await {
        let content_disposition = field.content_disposition();
        let filename = content_disposition.get_filename().unwrap_or("file").to_string();
        let unique_id = Uuid::new_v4().to_string();
        let sanitized_filename = sanitize_filename::sanitize(&filename);
        let full_path = Path::new(STORAGE_DIR).join(format!("{}_{}", unique_id, sanitized_filename));

        // Save the file
        let mut f = web::block(move || std::fs::File::create(&full_path)).await.unwrap().unwrap();
        while let Some(chunk) = field.next().await {
            let data = chunk.unwrap();
            f = web::block(move || f.write_all(&data)).await.unwrap().unwrap();
        }

        file_path = Some(full_path);
    }

    match file_path {
        Some(path) => {
            let id = path.file_name().unwrap().to_str().unwrap().to_string();
            HttpResponse::Ok().json(serde_json::json!({ "id": id }))
        }
        None => HttpResponse::BadRequest().json(serde_json::json!({ "error": "File upload failed" })),
    }
}

async fn share_image(web::Path(image_id): web::Path<String>) -> impl Responder {
    let file_path = Path::new(STORAGE_DIR).join(&image_id);

    if file_path.exists() {
        let mime_type = mime_guess::from_path(&file_path).first_or_octet_stream();
        let file = web::block(move || std::fs::File::open(file_path)).await;

        match file {
            Ok(file) => {
                HttpResponse::Ok()
                    .content_type(mime_type)
                    .body(web::block(move || {
                        let mut buf = Vec::new();
                        std::io::copy(&mut file.take(1_000_000), &mut buf).unwrap(); // Limit to 1MB for safety
                        buf
                    }).await.unwrap())
            }
            Err(_) => HttpResponse::InternalServerError().json(serde_json::json!({ "error": "Internal server error" })),
        }
    } else {
        HttpResponse::NotFound().json(serde_json::json!({ "error": "Image not found" }))
    }
}

use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use actix_multipart::Multipart;
use futures::stream::StreamExt;
use std::fs;
use std::process::Command;
use std::path::PathBuf;
use serde::Deserialize;

#[derive(Deserialize)]
struct GifRequest {
    targetSize: String,
    delay: Option<u32>,
    appendReverted: Option<bool>,
}

async fn create_gif(mut payload: Multipart) -> impl Responder {
    let mut images: Vec<PathBuf> = Vec::new();
    let mut target_size: Option<String> = None;
    let mut delay: Option<u32> = None;
    let mut append_reverted: Option<bool> = None;

    while let Some(item) = payload.next().await {
        let mut field = item.unwrap();
        let content_disposition = field.content_disposition().unwrap();
        let name = content_disposition.get_name().unwrap();

        match name {
            "images" => {
                let filename = format!("temp_{}", uuid::Uuid::new_v4());
                let filepath = PathBuf::from(format!("/tmp/{}", filename));
                let mut f = fs::File::create(&filepath).unwrap();
                while let Some(chunk) = field.next().await {
                    let data = chunk.unwrap();
                    f.write_all(&data).unwrap();
                }
                images.push(filepath);
            }
            "targetSize" => {
                target_size = Some(field.next().await.unwrap().unwrap().to_string());
            }
            "delay" => {
                delay = Some(field.next().await.unwrap().unwrap().parse().unwrap());
            }
            "appendReverted" => {
                append_reverted = Some(field.next().await.unwrap().unwrap().parse().unwrap());
            }
            _ => {}
        }
    }

    if images.is_empty() || target_size.is_none() {
        return HttpResponse::BadRequest().json("Images and target size are required.");
    }

    let target_size = target_size.unwrap();
    let delay = delay.unwrap_or(10);
    let append_reverted = append_reverted.unwrap_or(false);

    let mut convert_command = Command::new("convert");
    convert_command.args(&images);
    convert_command.arg("-delay").arg(delay.to_string());
    convert_command.arg("-resize").arg(target_size);
    convert_command.arg("output.gif");

    if append_reverted {
        convert_command.arg("output.gif").arg("-reverse");
    }

    let output = convert_command.output().expect("Failed to execute command");

    if !output.status.success() {
        return HttpResponse::InternalServerError().json("Failed to create GIF.");
    }

    HttpResponse::Ok()
        .content_type("image/gif")
        .body(fs::read("output.gif").unwrap())
}

#[actix_web::main]
async fn main() -> std::io::Result<()> {
    HttpServer::new(|| {
        App::new()
            .route("/create-gif", web::post().to(create_gif))
    })
    .bind("0.0.0.0:5000")?
