    ).unwrap();

    let tags = product.tags.join(",");
    conn.execute(
        "INSERT INTO products (product_name, tags) VALUES (?1, ?2)",
        params![product.product_name, tags],
    ).unwrap();

    HttpResponse::Ok().body("Product added successfully")
}

