      res.download(outputFilePath, 'concatenated.pdf', (err) => {
        if (err) {
          throw new Error('An error occurred while processing the files.');
        }
      });
    } catch (error) {
      throw new BadRequestException('An error occurred while processing the files.');
    }
  }
}
