  }

  private async init() {
    this.db = await open({
      filename: resolve(__dirname, '../db.sqlite3'),
      driver: Database,
    });
    await this.db.exec(`
      CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        email TEXT UNIQUE NOT NULL,
        password TEXT NOT NULL,
        name TEXT NOT NULL
      )
    `);
