    {
        $data = $request->validate([
            'content' => 'required|string',
            'username' => 'required|string',
        ]);

        DB::insert('INSERT INTO messages (content, username, created_at) VALUES (?, ?, ?)', [
            $data['content'],
            $data['username'],
            now(),
        ]);

        return response()->json(['message' => 'Message posted successfully'], 200);
    }
}
