    $products = DB::select($query, $tagsArray);

    $htmlResponse = '<h1>Recommended Products</h1><ul>';
    foreach ($products as $product) {
        $htmlResponse .= '<li>' . htmlspecialchars($product->product_name) . '</li>';
    }
