    $validatedData = $request->validate([
        'product_name' => 'required|string',
        'tags' => 'required|array',
        'tags.*' => 'string',
    ]);

    $productName = $validatedData['product_name'];
    $tags = $validatedData['tags'];

    DB::insert('INSERT INTO products (product_name, tag) VALUES (?, ?)', [$productName, implode(',', $tags)]);

